SELECT DISTINCT assessment_type
FROM learning_review_record
WHERE unit_id = #{unitId}
  AND entry_id = #{entryId}
  AND check_result = 'correct'
  AND deleted = 0

SELECT entry_id, assessment_type FROM learning_review_record WHERE unit_id = #{unitId} AND entry_id IN
#{entryId}
AND check_result = 'correct' AND deleted = 0 GROUP BY entry_id, assessment_type
